import{f as i,J as h,o as d,c as l,a6 as o,b as r,w as t,a as s,K as c,a7 as n,aa as p,ab as g,ac as m,ad as b,ae as u,af as f,ag as y,ah as w,ai as k,aj as E,ak as v,al as x,am as S,an as T,ao as A,ap as _,aq as C,ar as L,as as P,at as R,au as D,av as I}from"./chunks/framework.Dd1qhYRL.js";const H=JSON.parse('{"title":"Terminal UI","description":"","frontmatter":{},"headers":[],"relativePath":"tui.md","filePath":"tui.md"}'),M={name:"tui.md"};function B(F,e,N,Q,z,O){const a=h("Mermaid");return d(),l("div",null,[e[2]||(e[2]=o('<h1 id="terminal-ui" tabindex="-1">Terminal UI <a class="header-anchor" href="#terminal-ui" aria-label="Permalink to “Terminal UI”">​</a></h1><p>Run builds, apply changes, and explore the database from the keyboard.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><p><img src="'+p+'" alt="Adding a config, creating the database, building the schema, fast-forwarding changes, and browsing the result" loading="lazy"></p><p><code>noorm ui</code> takes no flags and opens on Home. Every other <code>noorm</code> command is a non-interactive CLI, and bare <code>noorm</code> prints the command list; see the <a href="/headless.html">CLI reference</a>.</p><h2 id="how-do-i-get-around" tabindex="-1">How do I get around? <a class="header-anchor" href="#how-do-i-get-around" aria-label="Permalink to “How do I get around?”">​</a></h2><p>Home opens four working screens with one key. Secrets hang off a config, and the schema explorer off the database menu:</p>',7)),(d(),r(n,null,{default:t(()=>[c(a,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Home%5B%22Home%22%5D%20--%3E%7Cc%7C%20Config%5B%22Config%20list%22%5D%0A%20%20%20%20Home%20--%3E%7Cg%7C%20Changes%5B%22Changes%20list%22%5D%0A%20%20%20%20Home%20--%3E%7Cr%7C%20Run%5B%22Run%20menu%22%5D%0A%20%20%20%20Home%20--%3E%7Cd%7C%20Db%5B%22Database%20menu%22%5D%0A%20%20%20%20Config%20--%3E%7Ck%7C%20Secrets%5B%22Secrets%20of%20the%3Cbr%2F%3Ehighlighted%20config%22%5D%0A%20%20%20%20Db%20--%3E%7Cx%7C%20Explore%5B%22Schema%20explorer%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><img src="'+g+'" alt="Home: status, quick actions, and recent activity" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key on Home</th><th>Opens</th></tr></thead><tbody><tr><td><code>r</code></td><td>Run menu</td></tr><tr><td><code>c</code></td><td>Config list</td></tr><tr><td><code>g</code></td><td>Changes list</td></tr><tr><td><code>d</code></td><td>Database menu</td></tr><tr><td><code>+</code></td><td>More: Settings, Vault, Identity, Lock</td></tr><tr><td><code>s</code>, <code>v</code>, <code>i</code>, <code>l</code></td><td>Settings, Vault, Identity, Lock, without going through More</td></tr><tr><td><code>u</code></td><td>Update</td></tr><tr><td><code>1</code></td><td>Run build</td></tr><tr><td><code>2</code></td><td>Fast-forward changes</td></tr><tr><td><code>3</code></td><td>Lock status</td></tr><tr><td><code>q</code></td><td>Quit</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Task</th><th>Keys</th></tr></thead><tbody><tr><td>Switch config</td><td><code>c</code>, <code>↓</code> to the config, <code>Enter</code></td></tr><tr><td>Fast-forward all changes</td><td><code>g</code>, <code>f</code></td></tr><tr><td>Run the build</td><td><code>r</code>, <code>b</code></td></tr><tr><td>Validate a config</td><td><code>c</code>, <code>+</code>, <code>v</code></td></tr></tbody></table><h2 id="which-keys-work-on-every-screen" tabindex="-1">Which keys work on every screen? <a class="header-anchor" href="#which-keys-work-on-every-screen" aria-label="Permalink to “Which keys work on every screen?”">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>Go back, or cancel the operation in flight</td></tr><tr><td><code>Ctrl+C</code></td><td>Quit</td></tr><tr><td><code>?</code></td><td>Help overlay. Any key closes it</td></tr><tr><td><code>Shift+L</code></td><td>Toggle the log viewer</td></tr><tr><td><code>Shift+Q</code></td><td>Open the SQL terminal</td></tr><tr><td><code>D</code></td><td>Toggle dry-run mode. The status bar shows <code>DRY</code></td></tr><tr><td><code>F</code></td><td>Toggle force mode. The status bar shows <code>FORCE</code></td></tr></tbody></table><p><code>D</code> applies to the run screens, <code>change ff</code>, and the database wipe, teardown, and transfer screens. <code>F</code> applies to the run screens and <code>change ff</code>.</p><p>While a text field takes input (a form field in edit mode, a search box, the SQL editor), every key above except <code>Ctrl+C</code> types its character instead. <code>?</code>, <code>D</code>, and <code>F</code> also stand down inside dialogs.</p><h3 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to “Lists”">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Move the cursor. Wraps at both ends, except on the changes list</td></tr><tr><td><code>Enter</code></td><td>Select</td></tr><tr><td><code>Esc</code></td><td>Back</td></tr><tr><td><code>1</code>-<code>9</code></td><td>Select by number, on lists that show numbers: Settings and the explorer</td></tr><tr><td><code>Space</code></td><td>Toggle an item, on multi-select lists. <code>Enter</code> then submits</td></tr></tbody></table><p>A list fits the window, so a taller terminal shows more rows. It keeps its cursor when you open an item and come back.</p><h3 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to “Forms”">​</a></h3><p>A form has two modes. <code>Enter</code> switches between them, so submitting is a place you navigate to:</p>',12)),(d(),r(n,null,{default:t(()=>[c(a,{id:"mermaid-316",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20Browse%0A%20%20%20%20Browse%20--%3E%20Edit%3A%20Enter%20on%20a%20text%20or%20select%20field%0A%20%20%20%20Edit%20--%3E%20Browse%3A%20Enter%20commits%0A%20%20%20%20Edit%20--%3E%20Browse%3A%20Esc%20reverts%0A%20%20%20%20Browse%20--%3E%20Actions%3A%20Down%20past%20the%20last%20field%0A%20%20%20%20Actions%20--%3E%20Browse%3A%20Down%20wraps%20to%20the%20first%20field%0A%20%20%20%20Actions%20--%3E%20%5B*%5D%3A%20Enter%20on%20the%20submit%20button%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o(`<table tabindex="0"><thead><tr><th>Mode</th><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td>Browse</td><td><code>↑</code> <code>↓</code>, <code>Tab</code>, <code>Shift+Tab</code></td><td>Move between fields, wrapping through the action row</td></tr><tr><td>Browse</td><td><code>Enter</code></td><td>Open the field for editing</td></tr><tr><td>Browse</td><td><code>Esc</code></td><td>Cancel the form</td></tr><tr><td>Edit</td><td><code>Enter</code></td><td>Commit and return to browse</td></tr><tr><td>Edit</td><td><code>Esc</code></td><td>Restore the value the field held when edit opened</td></tr><tr><td>Edit</td><td><code>Tab</code>, <code>Shift+Tab</code></td><td>Commit and move to the next or previous field</td></tr><tr><td>Actions</td><td><code>←</code> <code>→</code>, <code>Enter</code></td><td>Pick a button and activate it</td></tr></tbody></table><p>A checkbox toggles in place on <code>Enter</code> or <code>Space</code>. A select expands on <code>Enter</code>, moves with <code>↑</code> <code>↓</code>, and takes the highlighted option on a second <code>Enter</code>. A red <code>*</code> marks a required field. Submitting with one empty puts the cursor on it, with the error beside the value.</p><h3 id="mouse" tabindex="-1">Mouse <a class="header-anchor" href="#mouse" aria-label="Permalink to “Mouse”">​</a></h3><p>On by default, in lists and result grids:</p><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td>Click a row</td><td>Move the cursor to it</td></tr><tr><td>Double-click a row</td><td>Same as <code>Enter</code> on that row</td></tr><tr><td>Wheel</td><td>Move the cursor one row, or scroll a document</td></tr></tbody></table><p>A click acts on whatever already has focus. Clicking an unfocused list does nothing.</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>Mouse tracking takes click-drag text selection away from the terminal. Hold Option in macOS Terminal and iTerm2, or Shift in most others. To turn the mouse off, set <code>ui.mouse</code> in <code>.noorm/settings.yml</code>; <code>?</code> prints the same hint.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .noorm/settings.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    mouse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div></div><h2 id="what-does-esc-do-while-the-database-is-busy" tabindex="-1">What does Esc do while the database is busy? <a class="header-anchor" href="#what-does-esc-do-while-the-database-is-busy" aria-label="Permalink to “What does Esc do while the database is busy?”">​</a></h2><p>A screen waiting on the database says so and names the key:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Testing connection...  [Esc] Cancel</span></span></code></pre></div><p>That covers testing a config (add and edit), the force-release lock check, and the SQL terminal connecting or running a query. <code>Esc</code> returns the screen to a usable state and saves nothing. The client always stops waiting. Whether the server stops depends on the dialect:</p><table tabindex="0"><thead><tr><th>Dialect</th><th>Effect on the server</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>pg_cancel_backend</code> asks it to stop the statement</td></tr><tr><td>MySQL</td><td><code>KILL QUERY</code> stops the statement</td></tr><tr><td>SQL Server, SQLite</td><td>Nothing. The statement finishes. The message reads <code>Stopped waiting. The query may still be running on the server.</code></td></tr></tbody></table><p>A connect that answers after you cancelled is closed, not adopted. A connection attempt also ends on its own after 15 seconds. Raise <code>connection.connectTimeoutMs</code> for a link that is slow but working. <a href="/guide/database/terminal.html">The SQL terminal guide</a> has the full table.</p><h3 id="long-running-files" tabindex="-1">Long-Running Files <a class="header-anchor" href="#long-running-files" aria-label="Permalink to “Long-Running Files”">​</a></h3><p>A file that runs past 10 seconds gets a status block under its name, refreshed every 10 seconds. It appears on the run screens (Build, Exec, Dir, File) and the change screens (Run, Revert, Fast Forward, Next, Rewind):</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Current:  06_items.sql</span></span>
<span class="line"><span>Running for 17m05s  pid 4412</span></span>
<span class="line"><span>CREATE INDEX on items · building index: loading tuples · 4210/9800 (42%)  2 parallel workers</span></span>
<span class="line"><span>Waiting on pid 4411 (CREATE INDEX items_embedding ..., 17m04s) · Lock: transactionid</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Line</th><th>Appears when</th></tr></thead><tbody><tr><td><code>Running for … pid …</code></td><td>Always. SQLite shows elapsed time only</td></tr><tr><td>Operation progress</td><td>The server reports it: index builds, <code>VACUUM</code>, <code>CLUSTER</code>, <code>COPY</code>, <code>ANALYZE</code> on PostgreSQL; <code>percent_complete</code> on SQL Server; stage counters on MySQL</td></tr><tr><td><code>Waiting on pid …</code></td><td>The file waits on another session&#39;s lock</td></tr></tbody></table><p>On Run Build and Run Exec, press <code>Esc</code> once for a warning and again within 2 seconds to cancel. No further file starts. PostgreSQL and MySQL cancel the running statement. SQL Server and SQLite let it finish, and the screen says <code>Stopping after the current file finishes.</code> Leaving the screen does not cancel the run.</p><h2 id="what-does-each-screen-do" tabindex="-1">What does each screen do? <a class="header-anchor" href="#what-does-each-screen-do" aria-label="Permalink to “What does each screen do?”">​</a></h2><h3 id="config-list" tabindex="-1">Config List <a class="header-anchor" href="#config-list" aria-label="Permalink to “Config List”">​</a></h3><p><img src="`+m+'" alt="The configuration list" loading="lazy"></p><p>A config shows <code>●</code> when active and <code>○</code> when not, with <code>[user:&lt;role&gt; agent:&lt;role|off&gt;]</code> when its access differs from the default (<code>admin</code> for you, <code>viewer</code> for the agent) and <code>[test]</code> on a test config.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Make the highlighted config active. On the config that is already active, open its edit form</td></tr><tr><td><code>a</code></td><td>Add</td></tr><tr><td><code>e</code></td><td>Edit</td></tr><tr><td><code>d</code></td><td>Delete</td></tr><tr><td><code>c</code></td><td>Copy</td></tr><tr><td><code>k</code></td><td>Secrets of the highlighted config</td></tr><tr><td><code>+</code></td><td>More: <code>x</code> export, <code>i</code> import, <code>v</code> validate</td></tr></tbody></table><p>Adding a config is interactive only. <code>noorm config add</code> points here, and <code>noorm config import &lt;file.json&gt;</code> is the headless route.</p><p><img src="'+b+'" alt="The add-config form" loading="lazy"></p><p><code>User Role</code> covers a human on the CLI, TUI, or SDK. <code>Agent Role</code> covers an AI agent over MCP and the CLI. They are independent. <a href="/guide/environments/configs.html#access-roles">Configs</a> lists what each role permits.</p><h3 id="changes-list" tabindex="-1">Changes List <a class="header-anchor" href="#changes-list" aria-label="Permalink to “Changes List”">​</a></h3><p><img src="'+u+'" alt="The changes list" loading="lazy"></p><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td><code>✓</code></td><td>Applied</td></tr><tr><td><code>○</code></td><td>Pending</td></tr><tr><td><code>✗</code></td><td>Failed</td></tr><tr><td><code>↩</code></td><td>Reverted</td></tr><tr><td><code>!</code></td><td>Orphaned: recorded in the database, folder gone from disk</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Run a pending, failed, or reverted change. Revert an applied one</td></tr><tr><td><code>a</code></td><td>Add</td></tr><tr><td><code>e</code></td><td>Edit. Not for an orphaned change</td></tr><tr><td><code>d</code></td><td>Delete</td></tr><tr><td><code>r</code></td><td>Run. Pending, failed, or reverted only</td></tr><tr><td><code>v</code></td><td>Revert. Applied only</td></tr><tr><td><code>n</code></td><td>Next: apply the next N pending changes, one by default</td></tr><tr><td><code>f</code></td><td>Fast-forward all pending changes</td></tr><tr><td><code>w</code></td><td>Rewind</td></tr><tr><td><code>h</code></td><td>History</td></tr></tbody></table><p>With no changes, the list reads <code>No changes found. Press [a] to create one.</code></p><p><img src="'+f+'" alt="Change history" loading="lazy"></p><p>History lists what ran, when, and under which identity. <code>Enter</code> shows the files, and <code>e</code> shows the full error of a failed change.</p><h3 id="run-menu" tabindex="-1">Run Menu <a class="header-anchor" href="#run-menu" aria-label="Permalink to “Run Menu”">​</a></h3><p><img src="'+y+'" alt="The run menu" loading="lazy"></p><p><code>b</code> or <code>1</code> Build, <code>e</code> or <code>2</code> Exec, <code>f</code> or <code>3</code> File, <code>d</code> or <code>4</code> Dir, <code>i</code> or <code>5</code> Inspect.</p><p>A file that already ran with the same content opens <strong>File Previously Run</strong> and asks <code>Run this file again?</code>. A directory with such files opens <strong>Files Previously Run</strong>.</p><h3 id="database-menu" tabindex="-1">Database Menu <a class="header-anchor" href="#database-menu" aria-label="Permalink to “Database Menu”">​</a></h3><p><img src="'+w+'" alt="The database menu" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th><th>Needs a connection</th></tr></thead><tbody><tr><td><code>c</code></td><td>Create the database. Shows a toast if it is already initialized</td><td>No</td></tr><tr><td><code>d</code></td><td>Destroy</td><td>No</td></tr><tr><td><code>x</code></td><td>Explore</td><td>Yes</td></tr><tr><td><code>w</code></td><td>Wipe: truncate</td><td>Yes</td></tr><tr><td><code>t</code></td><td>Teardown</td><td>Yes</td></tr><tr><td><code>r</code></td><td>Transfer</td><td>Yes</td></tr></tbody></table><p>The SQL terminal is not on this menu. Open it with <code>Shift+Q</code>.</p><h3 id="schema-explorer" tabindex="-1">Schema Explorer <a class="header-anchor" href="#schema-explorer" aria-label="Permalink to “Schema Explorer”">​</a></h3><p><img src="'+k+'" alt="The explorer overview, with object counts by category" loading="lazy"></p><p>Each category opens from the overview by its letter or its number. A category with no objects does nothing.</p><table tabindex="0"><thead><tr><th>Category</th><th>Keys</th></tr></thead><tbody><tr><td>Tables</td><td><code>t</code>, <code>1</code></td></tr><tr><td>Views</td><td><code>v</code>, <code>2</code></td></tr><tr><td>Procedures</td><td><code>p</code>, <code>3</code></td></tr><tr><td>Functions</td><td><code>f</code>, <code>4</code></td></tr><tr><td>Types</td><td><code>y</code>, <code>5</code></td></tr><tr><td>Indexes</td><td><code>i</code>, <code>6</code></td></tr><tr><td>Foreign Keys</td><td><code>k</code>, <code>7</code></td></tr></tbody></table><p><img src="'+E+'" alt="The table list" loading="lazy"></p><p><code>Enter</code> on an object opens its detail. Indexes and foreign keys have none.</p><p><img src="'+v+'" alt="Table detail: columns, indexes, and foreign keys" loading="lazy"></p><p>A detail longer than the window scrolls. The footer lists only the keys the screen answers to.</p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Scroll one line</td></tr><tr><td><code>Ctrl+U</code>, <code>Ctrl+D</code></td><td>Half a page</td></tr><tr><td><code>PageUp</code>, <code>PageDown</code></td><td>A full page. On macOS the footer shows <code>fn ↑↓</code></td></tr><tr><td><code>Home</code>, <code>End</code></td><td>Top, bottom</td></tr><tr><td><code>v</code></td><td>Full text: the same rows with nothing truncated</td></tr><tr><td><code>r</code></td><td>Read rows. Tables only</td></tr></tbody></table><h3 id="reading-rows" tabindex="-1">Reading Rows <a class="header-anchor" href="#reading-rows" aria-label="Permalink to “Reading Rows”">​</a></h3><p><code>r</code> on a table detail reads its rows without leaving the explorer for the SQL terminal.</p><p><img src="'+x+'" alt="Peeking at both ends of a table, then opening one row as a document" loading="lazy"></p><p>The peek reads both ends of the table, so the last rows by primary key are as reachable as the first:</p><p><img src="'+S+'" alt="First and last rows, side by side" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Move the cursor within a set</td></tr><tr><td><code>Tab</code></td><td>Swap between the first set and the last</td></tr><tr><td><code>Enter</code></td><td>Open the highlighted row as a document</td></tr><tr><td><code>/</code></td><td>Filter. <code>Tab</code> cycles the column, <code>Enter</code> applies, <code>Esc</code> clears</td></tr><tr><td><code>s</code></td><td>Sort. <code>←</code> <code>→</code> pick the column, <code>a</code> ascending, <code>d</code> descending</td></tr><tr><td><code>c</code></td><td>Clear filter and sort</td></tr><tr><td><code>Esc</code></td><td>Close the peek</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td>The role lacks <code>sql:read</code></td><td>Refused. Reading rows needs <code>sql:read</code>, not the <code>explore</code> permission the other explorer screens use</td></tr><tr><td>The table has no primary key</td><td>Only the first rows appear: <code>No primary key, so there is no last set — rows are in storage order.</code></td></tr><tr><td>Both ends meet</td><td>One table, headed <code>All N rows</code></td></tr></tbody></table><p>The grid fits as many whole columns as the terminal holds and marks the rest <code>… N more columns</code>. <code>Enter</code> on a row shows them all:</p><p><img src="'+T+'" alt="One row as a YAML document" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>←</code> <code>→</code></td><td>Previous row, next row, in the order the table showed</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Scroll a document taller than the window</td></tr><tr><td><code>f</code></td><td>Swap YAML and JSON. The choice holds for the session</td></tr><tr><td><code>Esc</code></td><td>Back to the peek, on the row you were reading</td></tr></tbody></table><h3 id="sql-terminal" tabindex="-1">SQL Terminal <a class="header-anchor" href="#sql-terminal" aria-label="Permalink to “SQL Terminal”">​</a></h3><p><code>Shift+Q</code> opens the SQL terminal against the active config from any screen.</p><p><img src="'+A+'" alt="The SQL terminal" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Run the query</td></tr><tr><td><code>Shift+Enter</code></td><td>New line</td></tr><tr><td><code>Shift+Tab</code></td><td>Toggle edit mode, where <code>Enter</code> inserts a new line</td></tr><tr><td><code>↑</code> <code>↓</code></td><td>Walk query history, when the box is empty or already browsing</td></tr><tr><td><code>h</code></td><td>Open the history list, when the box is empty</td></tr><tr><td><code>Tab</code></td><td>Switch between the query and the results, once there are rows</td></tr><tr><td><code>Esc</code></td><td>In results: back to the query. With text in the box: clear it. Empty: go back. While a query runs: cancel it</td></tr></tbody></table><p>In the results grid, <code>/</code>, <code>s</code>, and <code>c</code> filter, sort, and clear as in the row peek, and <code>Enter</code> opens a row as a document. A result wider than the terminal keeps whole columns and marks the remainder <code>… N more columns</code>.</p><p>The history list takes <code>↑</code> <code>↓</code>, <code>Enter</code> to view a result, <code>r</code> to re-run a query, and <code>c</code> to clear.</p><h3 id="log-viewer" tabindex="-1">Log Viewer <a class="header-anchor" href="#log-viewer" aria-label="Permalink to “Log Viewer”">​</a></h3><p><code>Shift+L</code> toggles an overlay that tails events as they happen, newest first.</p><p><img src="'+_+'" alt="The log viewer overlay" loading="lazy"></p><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>/</code></td><td>Search. <code>Enter</code> leaves search, <code>Esc</code> clears it</td></tr><tr><td><code>g</code>, <code>G</code></td><td>Newest, oldest</td></tr><tr><td><code>↑</code> <code>↓</code>, <code>PageUp</code>, <code>PageDown</code></td><td>Move</td></tr><tr><td><code>Space</code></td><td>Pause or resume the tail</td></tr><tr><td><code>r</code></td><td>Refresh</td></tr><tr><td><code>Enter</code></td><td>Open one entry in full. <code>Esc</code> returns to the list</td></tr><tr><td><code>Shift+L</code>, <code>Esc</code></td><td>Close</td></tr></tbody></table><h3 id="more" tabindex="-1">More <a class="header-anchor" href="#more" aria-label="Permalink to “More”">​</a></h3><p><img src="'+C+'" alt="The More menu" loading="lazy"></p><p><code>+</code> from Home opens Settings (<code>s</code>), Vault (<code>v</code>), Identity (<code>i</code>), and Lock (<code>l</code>). Each also has its direct key on Home.</p><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to “Settings”">​</a></h3><p><img src="'+L+'" alt="The settings screen" loading="lazy"></p><p>Seven groups: Build, Paths, Stages, Rules, Strict, Logging, Secrets. <code>Enter</code> or a number opens one, and edits write to <code>.noorm/settings.yml</code>. <code>i</code> creates that file when the project has none. See <a href="/guide/sql-files/organization.html">SQL file organization</a> and <a href="/guide/environments/configs.html">Configs</a>.</p><h3 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to “Identity”">​</a></h3><p><img src="'+P+'" alt="The identity screen" loading="lazy"></p><p><code>e</code> edit, <code>x</code> export your public key, <code>r</code> regenerate, <code>u</code> known users. The identity lives in <code>~/.noorm/</code> and names who ran each change in the <a href="/guide/changes/history.html">history</a>. The CLI equivalent is <a href="/cli/identity.html"><code>noorm identity</code></a>.</p><h3 id="vault" tabindex="-1">Vault <a class="header-anchor" href="#vault" aria-label="Permalink to “Vault”">​</a></h3><p><img src="'+R+'" alt="The vault screen before initialization" loading="lazy"></p><p>The vault holds team-shared encrypted secrets in the database. It starts uninitialized: <code>i</code> creates it. After that, <code>a</code> adds a secret, <code>Enter</code> edits the highlighted one, and <code>p</code> propagates access to teammates. See <a href="/guide/environments/vault.html">Vault</a>.</p><h3 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to “Secrets”">​</a></h3><p><img src="'+D+'" alt="The secrets screen for a config" loading="lazy"></p><p><code>k</code> on the config list opens the highlighted config&#39;s secrets: <code>a</code> add, <code>e</code> or <code>Enter</code> edit, <code>d</code> delete. See <a href="/guide/environments/secrets.html">Secrets</a>.</p><h3 id="lock" tabindex="-1">Lock <a class="header-anchor" href="#lock" aria-label="Permalink to “Lock”">​</a></h3><p><img src="'+I+'" alt="The lock screen" loading="lazy"></p><p>noorm locks the database around writes, so two people building one environment do not interleave. On the lock menu, <code>s</code> or <code>1</code> shows status, <code>a</code> or <code>2</code> acquires, <code>r</code> or <code>3</code> releases, and <code>f</code> or <code>4</code> force-breaks a stale lock. The status screen also has <code>x</code> to extend. See <a href="/dev/lock.html">Locking</a>.</p><h3 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to “Update”">​</a></h3><p><code>u</code> from Home checks GitHub releases for a newer noorm. <code>i</code> installs it, <code>r</code> checks again, and <code>Esc</code> goes back.</p><p>A binary install reports its download as <code>42.0 / 73.0 MB (57%)</code> with a progress bar. Without a <code>Content-Length</code> it shows <code>9.0 MB received</code> and no bar. A stalled download resumes from the bytes on disk and shows <code>download stalled — no data for 30s — resuming (attempt N/5)...</code>. An npm install runs the package manager and shows none of this.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/headless.html">CLI reference</a>: the non-interactive surface</li><li><a href="/guide/database/terminal.html">The SQL terminal guide</a>: history, result browsing, per-dialect cancel</li><li><a href="/guide/sql-files/execution.html">Execution</a>: what the run screens do with each file</li><li><a href="/guide/environments/configs.html">Configs</a>: access roles</li></ul>',93))])}const V=i(M,[["render",B]]);export{H as __pageData,V as default};
